import * as THREE from 'three/webgpu';
import {
	MeshStandardNodeMaterial,
	mix,
	color,
	positionLocal,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<number>} [position]
 * @property {Array<number>} [rotation]
 * @property {Array<number>} [scale]
 * @property {Array<string>} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {THREE.TextureLoader} textureLoader
 * @property {THREE.GLTFLoader} glbLoader
 * @property {Object} primitives
 * @property {Object} fontAtlas
 */

/**
 * Create the Bento metrics grid node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	const root = new THREE.Group();

	// Apply transforms
	if (config.position) root.position.fromArray(config.position);
	if (config.rotation) root.rotation.fromArray(config.rotation);
	if (config.scale) root.scale.fromArray(config.scale);

	const timelines = [];

	/** --------------------------------------------------------------------
	 * Header caption
	 * -------------------------------------------------------------------- */
	const headerText = (config.textContent && config.textContent[0]) || '';
	const headerMesh = createText({
		text: headerText,
		fontFamily: 'Lora',
		fontSize: 18,
		fontWeight: 700,
		color: '#e8ecf2',
		atlas: ctx.fontAtlas,
		align: 'left',
	});
	// Header sits 0.5 units above the grid, left‑aligned to x = -2.75
	headerMesh.position.set(-2.75, 3.5 / 2 + 0.5, 0.01);
	root.add(headerMesh);

	/** --------------------------------------------------------------------
	 * Cell definitions
	 * -------------------------------------------------------------------- */
	const cells = [
		{
			// dominant cell (left column)
			name: 'dominant',
			width: 3.25,
			height: 3.5,
			value: (config.textContent && config.textContent[1]) || '',
			label: (config.textContent && config.textContent[2]) || '',
			valueStyle: { fontSize: 124, fontWeight: 600, family: 'Lora' },
			labelStyle: { fontSize: 18, fontWeight: 400, family: 'JetBrains Mono' },
			position: new THREE.Vector3(-1.125, 0, 0),
			valueEmHeight: 0.62,
		},
		{
			// upper secondary cell (right column, top)
			name: 'secondaryTop',
			width: 2.0,
			height: 1.625,
			value: (config.textContent && config.textContent[3]) || '',
			label: (config.textContent && config.textContent[4]) || '',
			valueStyle: { fontSize: 68, fontWeight: 600, family: 'Lora' },
			labelStyle: { fontSize: 18, fontWeight: 400, family: 'JetBrains Mono' },
			position: new THREE.Vector3(1.75, 0.9375, 0),
			valueEmHeight: 0.34,
		},
		{
			// lower secondary cell (right column, bottom)
			name: 'secondaryBottom',
			width: 2.0,
			height: 1.625,
			value: (config.textContent && config.textContent[5]) || '',
			label: (config.textContent && config.textContent[6]) || '',
			valueStyle: { fontSize: 68, fontWeight: 600, family: 'Lora' },
			labelStyle: { fontSize: 18, fontWeight: 400, family: 'JetBrains Mono' },
			position: new THREE.Vector3(1.75, -0.9375, 0),
			valueEmHeight: 0.34,
		},
	];

	/** --------------------------------------------------------------------
	 * Helper to build a cell
	 * -------------------------------------------------------------------- */
	function buildCell(cell, index) {
		const cellGroup = new THREE.Group();
		cellGroup.position.copy(cell.position);
		root.add(cellGroup);

		// ----------------------------------------------------------------
		// Slab (extruded slab)
		// ----------------------------------------------------------------
		const slabGeom = new THREE.BoxGeometry(cell.width, cell.height, 0.06);
		const slabMat = new MeshStandardNodeMaterial({
			// vertical gradient (approximation of engineered diagonal)
			colorNode: mix(
				color('#101017'),
				color('#1a1a22'),
				positionLocal.y
					.div(cell.height)
					.add(0.5)
			),
			metalness: 0.45,
			roughness: 0.5,
			clearcoat: 0.2,
			transparent: true,
			opacity: 0, // start invisible for entrance animation
		});
		const slab = new THREE.Mesh(slabGeom, slabMat);
		cellGroup.add(slab);

		// ----------------------------------------------------------------
		// Tick bar (emissive strip)
		// ----------------------------------------------------------------
		const tickGeom = new THREE.BoxGeometry(0.4, 0.05, 0.001);
		const tickMat = new MeshStandardNodeMaterial({
			color: 0xff2a38,
			emissive: 0xff2a38,
			emissiveIntensity: 1.3,
			metalness: 0,
			roughness: 0.5,
		});
		const tick = new THREE.Mesh(tickGeom, tickMat);
		const pad = 0.5; // inner padding
		const tickX = -cell.width / 2 + pad + 0.4 / 2;
		const tickY = cell.height / 2 - pad - 0.05 / 2;
		tick.position.set(tickX, tickY, 0.031);
		cellGroup.add(tick);

		// ----------------------------------------------------------------
		// Value text
		// ----------------------------------------------------------------
		const valueMesh = createText({
			text: cell.value,
			fontFamily: cell.valueStyle.family,
			fontSize: cell.valueStyle.fontSize,
			fontWeight: cell.valueStyle.fontWeight,
			color: '#e8ecf2',
			atlas: ctx.fontAtlas,
			align: 'center',
		});
		// Place roughly centred; vertical offset can be tweaked per design
		valueMesh.position.set(0, 0, 0.04);
		cellGroup.add(valueMesh);

		// ----------------------------------------------------------------
		// Label text (below value)
		// ----------------------------------------------------------------
		const labelMesh = createText({
			text: cell.label,
			fontFamily: cell.labelStyle.family,
			fontSize: cell.labelStyle.fontSize,
			fontWeight: cell.labelStyle.fontWeight,
			color: '#e8ecf2',
			atlas: ctx.fontAtlas,
			align: 'center',
		});
		// Offset 0.5 units downward from value
		labelMesh.position.set(0, -0.5, 0.04);
		cellGroup.add(labelMesh);

		// ----------------------------------------------------------------
		// Entrance animation (fade‑up + stagger)
		// ----------------------------------------------------------------
		const tl = gsap.timeline({ paused: true });
		tl.from(
			cellGroup.position,
			{ y: '+0.2', duration: 0.5, ease: 'power2.out' },
			0
		);
		tl.from(
			slabMat,
			{ opacity: 0, duration: 0.5, ease: 'power2.out' },
			0
		);
		// stagger according to index (dominant first)
		tl.delay(index * 0.08);
		tl.play();
		timelines.push(tl);

		// ----------------------------------------------------------------
		// Hover interaction (press‑down / weighted‑settle)
		// ----------------------------------------------------------------
		const pressDown = () => {
			gsap.to(cellGroup.scale, {
				x: 0.97,
				y: 0.97,
				z: 0.97,
				duration: 0.12,
				ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
			});
		};
		const release = () => {
			gsap
				.to(cellGroup.scale, {
					x: 1.04,
					y: 1.04,
					z: 1.04,
					duration: 0.9,
					ease: 'cubic-bezier(0.165,0.84,0.44,1)',
				})
				.then(() => {
					gsap.to(cellGroup.scale, {
						x: 1,
						y: 1,
						z: 1,
						duration: 0.2,
						ease: 'power2.out',
					});
				});
		};

		cellGroup.userData.handlers = {
			pointerover: pressDown,
			pointerout: release,
		};
	}

	// Build all cells
	cells.forEach(buildCell);

	/** --------------------------------------------------------------------
	 * Cleanup
	 * -------------------------------------------------------------------- */
	root.userData.cleanup = () => {
		// Kill GSAP timelines
		timelines.forEach((t) => t.kill());

		// Dispose three.js resources
		root.traverse((obj) => {
			if (obj.isMesh) {
				obj.geometry?.dispose();
				obj.material?.dispose();
			}
		});
	};

	// No global handlers for this node
	root.userData.handlers = {};

	return root;
}
